//! Calibrated display-math width estimation (M7.8 refinement).
//!
//! Glyph widths are probed from the Computer Modern math fonts at the
//! three math styles — display/text (10 pt), script (7 pt),
//! scriptscript (5 pt) — by `examples/auto-proof/math_probe_widths.py`;
//! the static table between the calibration markers is regenerated by
//! `math_emit_table.py`. The structural model reproduces TeX's spacing
//! rules as measured on composites:
//!
//! * scripts take their child-style glyph width plus `\scriptspace`
//!   (0.5 pt) and stack sub over sup (`max`, never the sum —
//!   `x_s^s` measures exactly `x^s`);
//! * fractions take the wider of numerator and denominator in the
//!   child style plus `\nulldelimiterspace` on both sides (2×1.2 pt);
//! * radicals add a style-dependent radical-symbol overhead;
//! * `\sum`-family operators stack their limits in display style
//!   (width = max of glyph and scripts) while `\int`-family and
//!   scripts in script styles place them beside the glyph;
//! * operator names (`\max`, `\lim`, …) widen only when their
//!   below-limits exceed the word;
//! * relations carry two thickmuskip glues, binaries two medmuskip
//!   glues, and `\left`/`\right` carry per-delimiter footprints
//!   (distinct from the plain delimiters, which use other font
//!   variants).
//!
//! The estimate decides column vs. strip vs. split (M7.8): a strip is
//! always legal, an overflow is not, so unknown constructs err on the
//! wide side.

/// Style index: 0 = display/text (10 pt), 1 = script (7 pt),
/// 2 = scriptscript (5 pt).
type Style = usize;

