/// `\scriptspace` = 0.5 pt: right-bearing of a script over its base.
const SCRIPTSPACE: f64 = 0.0176;
/// 2 × `\nulldelimiterspace` (1.2 pt on each side of a fraction).
const NULLDELIM2: f64 = 0.0843;
/// 3 mu: thin space (`\,`); also the TeX class-glue unit.
const THIN: f64 = 0.0586;
/// 4 mu: medium class glue (binary).
const MED: f64 = 0.0781;
/// 5 mu: thick class glue (relation).
const THICK: f64 = 0.0976;
/// One em at the document size (`\quad`).
const QUAD: f64 = 0.3515;
/// Prime mark (`x'` = base + 2.806 pt).
const PRIME: f64 = 0.0989;
/// Radical-symbol overhead per style (`\sqrt{gggggg}` − 6·g).
const RAD_OVER: [f64; 3] = [0.2929, 0.2309, 0.1928];
/// Matrix inter-column glue: 2 × `\arraycolsep` = 10 pt.
const MAT_GAP: f64 = 0.3515;
/// Delimiter-pair overhead of matrix environments.
fn matrix_brack(env: &str) -> f64 {
    match env {
        "bmatrix" | "Bmatrix" => 0.371,
        "pmatrix" | "vmatrix" => 0.5174,
        _ => 0.0,
    }
}
/// Width inflation of bold math relative to the regular face.
const BOLD_FACTOR: f64 = 1.2;
/// Fallback for commands outside the probed inventory.
const UNKNOWN_CMD: f64 = 0.22;

/// Width of one `\tag`-stripped display span in cm: the widest of its
/// `\\`-separated rows. Public because the display splitter (M7.8)
/// and the emission path both consult it.
pub(crate) fn display_math_width_cm(tex: &str) -> f64 {
    // A display holds one equation; `\\` separates its rows.
    let mut tex = tex.to_string();
    // Excise the tag: it sits in the margin, never binds the width.
    while let Some(i) = tex.find("\\tag{") {
        // Inside the tag's brace already: depth starts at 1.
        let mut depth = 1usize;
        let mut j = i + 5;
        let bytes = tex.as_bytes();
        while j < bytes.len() {
            match bytes[j] {
                b'{' => depth += 1,
                b'}' => {
                    depth -= 1;
                    if depth == 0 {
                        j += 1;
                        break;
                    }
                }
                _ => {}
            }
            j += 1;
        }
        tex.replace_range(i..j.min(tex.len()), "");
    }
    split_display_rows(&tex)
        .iter()
        .map(|row| row_cm(row, 0, false))
        .reduce(f64::max)
        .unwrap_or(0.0)
}

/// Split a display on `\\\\` row breaks, ignoring `\\\\` inside
/// `matrix` environments (their rows size inside-out via `row_cm`;
/// splitting there would measure shards).
fn split_display_rows(tex: &str) -> Vec<&str> {
    let mut rows = Vec::new();
    let mut depth = 0i32;
    let mut start = 0usize;
    let mut i = 0usize;
    while i < tex.len() {
        if let Some((len, is_begin, _)) = matrix_token_at(tex, i) {
            depth = if is_begin { depth + 1 } else { (depth - 1).max(0) };
            i += len;
            continue;
        }
        if depth == 0 && tex[i..].starts_with("\\\\") {
            rows.push(&tex[start..i]);
            i += 2;
            start = i;
            continue;
        }
        i += 1;
    }
    rows.push(&tex[start..]);
    rows
}

/// If `s[i..]` opens or closes a matrix-flavored environment, return
/// the full token length, whether it is a `\begin`, and the bracket
/// overhead of the flavor.
fn matrix_token_at(s: &str, i: usize) -> Option<(usize, bool, f64)> {
    if !s[i..].starts_with('\\') {
        return None;
    }
    let rest = &s[i + 1..];
    let (head, is_begin) = if rest.starts_with("begin{") {
        ("begin{", true)
    } else if rest.starts_with("end{") {
        ("end{", false)
    } else {
        return None;
    };
    let after = &rest[head.len()..];
    let close = after.find('}')?;
    let env = &after[..close];
    let flavor = match env {
        "matrix" | "bmatrix" | "Bmatrix" | "pmatrix" | "vmatrix" => env,
        _ => return None,
    };
    Some((1 + head.len() + close + 1, is_begin, matrix_brack(flavor)))
}

/// Math atom classes for inter-atom glue (TeXbook ch. 18).
const C_START: u8 = 0;
const C_ORD: u8 = 1;
const C_OP: u8 = 2;
const C_BIN: u8 = 3;
const C_REL: u8 = 4;
const C_OPEN: u8 = 5;
const C_CLOSE: u8 = 6;
const C_PUNCT: u8 = 7;
const C_INNER: u8 = 8;

/// Inter-atom glue in units (0 none, 1 thin, 2 med, 3 thick), rows =
/// previous class (0 = list start), cols = current class. Values
/// measured on composites (`x\sum`, `x=x`, `\frac ab x`, ...): they
/// agree with the TeXbook table where the book is explicit and settle
/// the boundary cases (Ord→Open/Close are thin, Rel is thick on both
/// sides, a leading Bin loses its operand glue).
static GLUE: [[u8; 9]; 9] = [
    [0, 0, 0, 0, 0, 0, 0, 0, 0], // start of list
    [0, 0, 1, 2, 3, 1, 0, 0, 0], // Ord (nothing before a closing fence)
    [0, 1, 1, 2, 3, 1, 1, 1, 1], // Op
    [0, 2, 2, 0, 0, 2, 2, 2, 2], // Bin
    [0, 3, 3, 0, 0, 3, 3, 3, 3], // Rel
    [0, 0, 0, 0, 0, 0, 0, 0, 0], // Open
    [0, 1, 1, 2, 3, 1, 1, 1, 1], // Close
    [0, 1, 1, 0, 1, 1, 1, 1, 1], // Punct
    [0, 0, 1, 2, 3, 1, 1, 1, 0], // Inner
];

/// Class glue in cm: zero in script styles (TeX inserts no class
/// glue below display/text style), else thin/med/thick by units.
fn glue_cm(units: u8, style: Style) -> f64 {
    if style > 0 || units == 0 {
        return 0.0;
    }
    match units {
        1 => THIN,
        2 => MED,
        3 => THICK,
        _ => 0.0,
    }
}

/// Does this fragment hold an Inner atom (fraction, nested
/// radical, matrix) at any level? Coarse: nesting inside another
/// wrapper still counts (the thin-pad errs on the wide side).
fn inner_top(s: &str) -> bool {
    s.contains("\\frac") || s.contains("\\sqrt") || s.contains("\\begin{")
}

/// Width of one `\\`-free display row at the given math style.
/// `text_ctx` marks arguments of a fraction/radical: a fraction
/// found there is a text-style fraction whose own children descend
/// to script size (measured on `\frac{\frac{s}{t}}{u}`).
fn row_cm(row: &str, style: Style, text_ctx: bool) -> f64 {
    let mut style = style;
    // Matrices bank their width and leave a zero-width placeholder:
    // a matrix sits INLINE (text + matrix + text sum on one row),
    // so max() would undercount side-by-side content.
    let mut bank = 0.0;
    let mut s = row.to_string();
    loop {
        let Some((brack, mstart, inner, mend)) = find_matrix(&s) else { break };
        // Matrix columns ALIGN: the environment is as wide as the
        // sum of per-column maxima plus inter-column glue — not the
        // max over rows of row sums (a tall narrow column would
        // otherwise undercount the aligned grid).
        let rows: Vec<Vec<&str>> = split_display_rows(&inner)
            .iter()
            .map(|r| r.split('&').collect())
            .collect();
        let ncols = rows.iter().map(|r| r.len()).max().unwrap_or(0);
        let mut total = 0.0;
        for c in 0..ncols {
            total += rows
                .iter()
                .filter_map(|r| r.get(c))
                .map(|cell| row_cm(cell, style, text_ctx))
                .fold(0.0f64, f64::max);
        }
        let widest = total + MAT_GAP * ncols.saturating_sub(1) as f64 + brack;
        bank += widest;
        s = format!("{}\u{E000}{}", &s[..mstart], &s[mend..]);
    }
    let mut w = bank;
    // Previous atom's class for inter-atom glue (None = list start).
    let mut prev = C_START;
    let mut cs = s.chars().peekable();
    while let Some(c) = cs.next() {
        if c == '\\' {
            let mut name = String::new();
            while let Some(&d) = cs.peek() {
                if d.is_ascii_alphabetic() {
                    name.push(d);
                    cs.next();
                } else {
                    break;
                }
            }
            if name.is_empty() {
                // `\{`, `\}`, `\%`, `\,` ... two-char command.
                match cs.next() {
                    Some(',') => w += 0.1389,
                    Some(':') => w += 0.0308,
                    Some(';') => w += 0.0385,
                    Some('!') => w -= THIN,
                    Some('{') | Some('}') => {
                        w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                        w += 0.1757;
                        prev = C_ORD;
                    }
                    Some(' ') | Some('\\') | Some('%') | Some('$') | Some('&') => {}
                    Some(_) => {
                        w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                        w += UNKNOWN_CMD;
                        prev = C_ORD;
                    }
                    None => {}
                }
                continue;
            }
            // Style switches change the active math size.
            if matches!(
                name.as_str(),
                "displaystyle" | "textstyle" | "scriptstyle" | "scriptscriptstyle"
            ) {
                style = match name.as_str() {
                    "scriptstyle" => 1,
                    "scriptscriptstyle" => 2,
                    _ => 0,
                };
                continue;
            }
            // Operator names: limits stack below in display style
            // (the word only widens when the script exceeds it).
            if matches!(
                name.as_str(),
                "max" | "min" | "sup" | "inf" | "lim" | "liminf" | "limsup" | "Pr"
                    | "cos" | "sin" | "tan" | "log" | "exp" | "ker"
            ) {
                w += glue_cm(GLUE[prev as usize][C_OP as usize], style);
                let atom = glyph_cm(&name, style).unwrap_or(UNKNOWN_CMD);
                let sc = take_scripts(&mut cs, style, text_ctx);
                w += match sc {
                    Some(s) => atom.max(s),
                    None => atom,
                };
                prev = C_OP;
                continue;
            }
            // `\sum`-family: limits stack in display style, sit
            // beside the glyph in script styles.
            if matches!(
                name.as_str(),
                "sum" | "prod" | "coprod" | "bigcup" | "bigcap"
            ) {
                w += glue_cm(GLUE[prev as usize][C_OP as usize], style);
                let atom = glyph_cm(&name, style).unwrap_or(UNKNOWN_CMD);
                let sc = take_scripts(&mut cs, style, text_ctx);
                w += match (sc, style) {
                    (Some(s), 0) => atom.max(s),
                    (Some(s), _) => atom + s + SCRIPTSPACE,
                    (None, _) => atom,
                };
                prev = C_OP;
                continue;
            }
            // `\int`-family: scripts always beside the glyph.
            if matches!(name.as_str(), "int" | "iint" | "iiint" | "oint") {
                w += glue_cm(GLUE[prev as usize][C_OP as usize], style);
                let atom = glyph_cm(&name, style).unwrap_or(UNKNOWN_CMD);
                let sc = take_scripts(&mut cs, style, text_ctx);
                w += atom + sc.map(|s| s + SCRIPTSPACE).unwrap_or(0.0);
                prev = C_OP;
                continue;
            }
            match name.as_str() {
                "left" => {
                    w += glue_cm(GLUE[prev as usize][C_OPEN as usize], style);
                    // Per-delimiter footprint (auto-sized variant,
                    // including its `\nulldelimiterspace`): differs
                    // from the plain delimiter's width.
                    w += lr_delim(&mut cs);
                    prev = C_OPEN;
                }
                "right" => {
                    w += glue_cm(GLUE[prev as usize][C_CLOSE as usize], style);
                    w += lr_delim(&mut cs);
                    prev = C_CLOSE;
                }
                "frac" | "dfrac" | "tfrac" | "sqrt" => {
                    w += glue_cm(GLUE[prev as usize][C_INNER as usize], style);
                    if name == "sqrt" {
                        // Optional `[n]` root index adds nothing.
                        if cs.peek() == Some(&'[') {
                            take_bracket(&mut cs);
                        }
                        let a = take_group(&mut cs);
                        // A radical around an Inner (fraction,
                        // nested radical, matrix) carries one thin
                        // space (measured on `\sqrt{rac{a}{b}}`).
                        let thin_pad =
                            if inner_top(&a) { THIN } else { 0.0 };
                        w += row_cm(&a, style, text_ctx)
                            + RAD_OVER[style.min(2)]
                            + thin_pad;
                    } else {
                        let a = take_group(&mut cs);
                        let b = take_group(&mut cs);
                        // Display fractions set num/den in text
                        // style (same widths); script fractions go
                        // to scriptscript.
                        let child = if style == 0 {
                        if text_ctx { 1 } else { 0 }
                    } else {
                        2
                    };
                        w += row_cm(&a, child, true).max(row_cm(&b, child, true))
                            + NULLDELIM2;
                    }
                    prev = C_INNER;
                }
                "text" | "mathrm" | "textrm" | "operatorname" => {
                    w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                    let a = take_group(&mut cs);
                    w += a.chars()
                        .filter(|c| !c.is_whitespace())
                        .map(|c| roman_cm(c, style))
                        .sum::<f64>();
                    prev = C_ORD;
                }
                "mathcal" => {
                    w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                    let a = take_group(&mut cs);
                    w += a.chars()
                        .filter(|c| c.is_ascii_uppercase())
                        .map(|c| cal_cm(c, style))
                        .sum::<f64>();
                    prev = C_ORD;
                }
                "mathbb" => {
                    w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                    let a = take_group(&mut cs);
                    w += a.chars()
                        .filter(|c| c.is_ascii_uppercase())
                        .map(|c| bb_cm(c, style))
                        .sum::<f64>();
                    prev = C_ORD;
                }
                "mathbf" | "boldsymbol" | "bm" | "bold" => {
                    w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                    let a = take_group(&mut cs);
                    w += row_cm(&a, style, text_ctx) * BOLD_FACTOR;
                    prev = C_ORD;
                }
                "overset" | "underset" => {
                    w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                    let a = take_group(&mut cs);
                    let b = take_group(&mut cs);
                    // Stacked over/under: max of the parts at the
                    // child style, no scriptspace (measured on
                    // `\overset{\sim}{\vartheta}`).
                    let child = script_style(style);
                    w += row_cm(&a, child, text_ctx).max(row_cm(&b, style, text_ctx));
                    prev = C_ORD;
                }
                "hat" | "bar" | "vec" | "tilde" | "widehat" | "widetilde"
                | "overline" | "underline" | "mathring" | "check" | "breve" => {
                    // Accents/rules add no width: widest arg decides.
                    let a = take_group(&mut cs);
                    w += row_cm(&a, style, text_ctx);
                }
                "quad" => w += QUAD,
                "qquad" => w += 2.0 * QUAD,
                "langle" | "rangle" | "Vert" | "vert" | "cdots" | "vdots"
                | "wp" | "hbar" | "infty" | "ldots" | "dots" => {
                    w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                    w += glyph_cm(&name, style).unwrap_or(UNKNOWN_CMD);
                    prev = C_ORD;
                }
                _ => {
                    // Class of this command when bare: relations and
                    // binaries carry their mu-glue; everything else
                    // (Greek letters, dots) is Ord.
                    let bare_cls = if matches!(
                        name.as_str(),
                        "leq" | "geq" | "neq" | "approx" | "equiv" | "sim" | "simeq"
                        | "cong" | "to" | "gets" | "leftarrow" | "rightarrow"
                        | "leftrightarrow" | "Rightarrow" | "Longrightarrow"
                        | "implies" | "in" | "ni" | "notin" | "subset" | "supset"
                        | "subseteq" | "supseteq" | "propto" | "perp" | "parallel"
                        | "mid" | "ll" | "gg" | "prec" | "succ" | "subsetneq"
                    ) {
                        C_REL
                    } else if matches!(
                        name.as_str(),
                        "pm" | "mp" | "times" | "div" | "cdot" | "circ" | "ast"
                        | "star" | "cap" | "cup" | "oplus" | "otimes" | "ominus"
                        | "wedge" | "vee" | "setminus" | "sqcap" | "sqcup"
                    ) {
                        C_BIN
                    } else {
                        C_ORD
                    };
                    // Wrappers (fonts, extenders): the widest braced
                    // argument decides (sub/superscripts attach).
                    let mut best = 0.0f64;
                    let mut any = false;
                    while cs.peek() == Some(&'{') {
                        any = true;
                        let g = take_group(&mut cs);
                        best = best.max(row_cm(&g, style, text_ctx));
                    }
                    if any {
                        w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
                        w += best;
                        prev = C_ORD;
                    } else {
                        // Probed bare glyph (Greek letters, classed
                        // relations/binaries) or unknown command.
                        w += glue_cm(GLUE[prev as usize][bare_cls as usize], style);
                        w += glyph_cm(&name, style).unwrap_or(UNKNOWN_CMD);
                        prev = bare_cls;
                    }
                }
            }
        } else if c == '^' || c == '_' {
            // `c` is the first script marker (the outer loop consumed
            // it). Scripts stack (sub under sup): width = max of the
            // script contents plus one scriptspace, never the sum
            // (`x_s^s` measures exactly `x^s`). Class unchanged.
            let mut best = script_content(&mut cs, style, text_ctx);
            while cs.peek() == Some(&'_') || cs.peek() == Some(&'^') {
                cs.next();
                best = best.max(script_content(&mut cs, style, text_ctx));
            }
            w += best + SCRIPTSPACE;
        } else if c == '{' || c == '}' || c == '~' || c == ' ' || c == '\t' {
            // Grouping / non-breaking space: no width.
        } else if c == '&' {
            // Alignment tab: the next cell starts a fresh math list
            // (aligned continuations begin with `& = ...`).
            prev = C_START;
        } else if c == '=' || c == '<' || c == '>' {
            // Relation: glyph plus class glue both sides.
            w += glue_cm(GLUE[prev as usize][C_REL as usize], style);
            w += glyph_cm(rel_key(c), style).unwrap_or(UNKNOWN_CMD);
            prev = C_REL;
        } else if c == '+' || c == '-' {
            // Binary op: glyph plus class glue both sides (unary
            // slightly overcounts: safe side).
            w += glue_cm(GLUE[prev as usize][C_BIN as usize], style);
            w += glyph_cm(if c == '+' { "plus" } else { "minus" }, style)
                .unwrap_or(UNKNOWN_CMD);
            prev = C_BIN;
        } else if c == ',' || c == ';' || c == ':' {
            w += glue_cm(GLUE[prev as usize][C_PUNCT as usize], style);
            w += if c == ',' { 0.0976 } else { 0.08 };
            prev = C_PUNCT;
        } else if c == '!' {
            w -= THIN;
        } else if c == '\'' {
            w += PRIME;
        } else if c == '\u{E000}' {
            // Banked matrix placeholder: an Inner atom.
            w += glue_cm(GLUE[prev as usize][C_INNER as usize], style);
            prev = C_INNER;
        } else if c.is_ascii_alphanumeric() {
            w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
            w += glyph_cm(&c.to_string(), style).unwrap_or(UNKNOWN_CMD);
            prev = C_ORD;
        } else if "()[]|/".contains(c) {
            // Plain delimiters are Ord atoms.
            let key = match c {
                '(' => "lpar",
                ')' => "rpar",
                '[' => "lbrk",
                ']' => "rbrk",
                '|' => "pipe",
                _ => "slash",
            };
            w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
            w += glyph_cm(key, style).unwrap_or(UNKNOWN_CMD);
            prev = C_ORD;
        } else {
            w += glue_cm(GLUE[prev as usize][C_ORD as usize], style);
            w += UNKNOWN_CMD;
            prev = C_ORD;
        }
    }
    w
}

/// Child style for scripts: 10 pt base → 7 pt; 7/5 pt → 5 pt
/// (`x_s` measures with the sub at script size, not scriptscript).
fn script_style(style: Style) -> Style {
    (style + 1).min(2)
}

/// Relation key for a character.
fn rel_key(c: char) -> &'static str {
    match c {
        '=' => "eq",
        '<' => "lt",
        _ => "gt",
    }
}

/// `\left`/`\right` delimiter footprint including its
/// `\nulldelimiterspace` (1.2 pt): the auto-sized cmex variant is
/// measured separately from the plain delimiter.
fn lr_delim(cs: &mut std::iter::Peekable<std::str::Chars>) -> f64 {
    if cs.peek() == Some(&'\\') {
        cs.next();
        let mut name = String::new();
        while let Some(&d) = cs.peek() {
            if d.is_ascii_alphabetic() {
                name.push(d);
                cs.next();
            } else {
                break;
            }
        }
        return match name.as_str() {
            "langle" | "rangle" | "lceil" | "rceil" | "lfloor" | "rfloor" => 0.1367,
            "Vert" | "vert" | "lVert" | "lvert" => 0.176,
            "lbrace" | "rbrace" => 0.176,
            "uparrow" | "downarrow" | "updownarrow" | "Uparrow" | "Downarrow"
            | "Updownarrow" => 0.176,
            "." => 0.0423,
            _ => 0.1367,
        };
    }
    match cs.next() {
        Some('(') | Some(')') => 0.1367,
        Some('[') | Some(']') => 0.0976,
        Some('{') | Some('}') => 0.176,
        Some('|') | Some('/') => 0.176,
        _ => 0.0423, // `\left.` / `\right.`: nulldelimiter only
    }
}

/// Probed glyph width (cm) at a math style.
fn glyph_cm(key: &str, style: Style) -> Option<f64> {
    GLYPH_W
        .iter()
        .find(|(k, _)| *k == key)
        .map(|(_, v)| v[style.min(2)])
}

/// Roman (cmr) glyph width for `\text`/`\mathrm`: probed per
/// lowercase letter and digit under the `R` prefix.
fn roman_cm(c: char, style: Style) -> f64 {
    if !c.is_ascii_alphanumeric() {
        return 0.16;
    }
    let key = format!("R{}", c);
    glyph_cm(&key, style).unwrap_or(0.16)
}

/// Calligraphic width for `\mathcal`: probed (display style) for the
/// letters the corpus uses; average otherwise; scaled for script
/// styles.
fn cal_cm(c: char, style: Style) -> f64 {
    const CAL_W: &[(char, f64)] = &[
        ('A', 0.2806), ('D', 0.2809), ('F', 0.2875), ('L', 0.2424),
        ('R', 0.2979), ('S', 0.2392), ('T', 0.2807),
    ];
    let d = CAL_W
        .iter()
        .find(|(k, _)| *k == c)
        .map(|(_, v)| *v)
        .unwrap_or(0.2684);
    match style {
        0 => d,
        1 => d * 0.8,
        _ => d * 0.72,
    }
}

/// Blackboard width for `\mathbb`: probed for R/N/E/P; average
/// otherwise; scaled for script styles.
fn bb_cm(c: char, style: Style) -> f64 {
    const BB_W: &[(char, f64)] = &[
        ('R', 0.2538), ('N', 0.2538), ('E', 0.2343), ('P', 0.2148),
    ];
    let d = BB_W
        .iter()
        .find(|(k, _)| *k == c)
        .map(|(_, v)| *v)
        .unwrap_or(0.2391);
    match style {
        0 => d,
        1 => d * 0.8,
        _ => d * 0.72,
    }
}

/// Find the next matrix environment: returns (bracket overhead,
/// start of `\begin`, inner source, end offset past `\end{...}`).
fn find_matrix(s: &str) -> Option<(f64, usize, String, usize)> {
    let mut i = 0usize;
    while i < s.len() {
        let Some((len, true, brack)) = matrix_token_at(s, i) else {
            // Advance to the next backslash (byte-level: a backslash
            // byte never occurs inside a multi-byte UTF-8 char),
            // keeping it: tokens start WITH a backslash, so stepping
            // over it would miss every `\begin`.
            match s[i..].as_bytes().iter().position(|&b| b == b'\\') {
                // A non-matrix command under the cursor: step over
                // its backslash (off = 0) to avoid spinning.
                Some(0) => i += 1,
                Some(off) => i += off,
                None => return None,
            }
            continue;
        };
        let inner_start = i + len;
        // Depth-matched close: nested matrices (A=(...)) must pair
        // with their own end, not the first one in the row.
        let mut d = 1i32;
        let mut k = inner_start;
        let mut close_start = None;
        while k < s.len() {
            if let Some((l2, is_begin, _)) = matrix_token_at(s, k) {
                if is_begin {
                    d += 1;
                } else {
                    d -= 1;
                    if d == 0 {
                        close_start = Some(k);
                    }
                }
                k += l2;
                if close_start.is_some() {
                    break;
                }
                continue;
            }
            k += 1;
        }
        let close_start = close_start?;
        let inner = s[inner_start..close_start].to_string();
        return Some((brack, i, inner, k));
    }
    None
}

/// Consume one `{...}` group (caller ate the `{`), nested-aware.
fn take_group(cs: &mut std::iter::Peekable<std::str::Chars>) -> String {
    let mut out = String::new();
    if cs.peek() != Some(&'{') {
        return out;
    }
    cs.next();
    let mut depth = 1usize;
    for c in cs.by_ref() {
        match c {
            '{' => {
                depth += 1;
                out.push(c);
            }
            '}' => {
                depth -= 1;
                if depth == 0 {
                    break;
                }
                out.push(c);
            }
            _ => out.push(c),
        }
    }
    out
}

/// Consume one `[...]` optional argument.
fn take_bracket(cs: &mut std::iter::Peekable<std::str::Chars>) {
    if cs.peek() == Some(&'[') {
        for c in cs.by_ref() {
            if c == ']' {
                break;
            }
        }
    }
}

/// Measure one script's content: the marker (`^`/`_`) is already
/// consumed; the content is a braced group, a `\command`, or a
/// single character, set at the child style.
fn script_content(
    cs: &mut std::iter::Peekable<std::str::Chars>,
    style: Style,
    text_ctx: bool,
) -> f64 {
    let child = script_style(style);
    if cs.peek() == Some(&'{') {
        let inner = take_group(cs);
        row_cm(&inner, child, text_ctx)
    } else {
        match cs.peek() {
            Some('\\') => {
                cs.next();
                let mut nm = String::new();
                while let Some(&d) = cs.peek() {
                    if d.is_ascii_alphabetic() {
                        nm.push(d);
                        cs.next();
                    } else {
                        break;
                    }
                }
                glyph_cm(&nm, child).unwrap_or(UNKNOWN_CMD)
            }
            Some(_) => {
                let ch = cs.next().unwrap();
                if ch.is_ascii_alphanumeric() {
                    glyph_cm(&ch.to_string(), child).unwrap_or(UNKNOWN_CMD)
                } else {
                    UNKNOWN_CMD
                }
            }
            None => 0.0,
        }
    }
}

/// Take consecutive `^`/`_` script groups (markers still in the
/// stream); returns the widest script content at the child style
/// (scripts stack, so max — not sum).
fn take_scripts(
    cs: &mut std::iter::Peekable<std::str::Chars>,
    style: Style,
    text_ctx: bool,
) -> Option<f64> {
    let mut best: Option<f64> = None;
    while cs.peek() == Some(&'_') || cs.peek() == Some(&'^') {
        cs.next();
        let g = script_content(cs, style, text_ctx);
        best = Some(best.map_or(g, |b: f64| b.max(g)));
    }
    best
}

#[cfg(test)]
mod tests {
    use super::display_math_width_cm as w;

    /// Assert the estimate against TeX-measured truth (cm) within
    /// 0.01: the probe composites in glyphs_raw.json, generated by
    /// examples/auto-proof/math_probe_widths.py.
    fn eq(name: &str, tex: &str, truth_cm: f64) {
        let got = w(tex);
        assert!(
            (got - truth_cm).abs() < 0.01,
            "{name}: got {got:.4}, TeX says {truth_cm:.4}"
        );
    }

    #[test]
    fn calibrated_constructs() {
        // Fractions: max(num, den) + 2 nulldelimiterspace.
        eq("frac-st", r"\frac{s}{t}", 0.249);
        eq("frac-ab", r"\frac{a}{b}", 0.2706);
        // Radicals: content + per-style overhead.
        eq("sqrt-6g", r"\sqrt{gggggg}", 1.3741);
        eq("sqrt-2g", r"\sqrt{gg}", 0.6531);
        // Scripts: base + child glyph + scriptspace; stacked max.
        eq("x-sup-s", "x^{s}", 0.3512);
        eq("x-sub-s", "x_{s}", 0.3512);
        eq("x-subsup-s", "x_{s}^{s}", 0.3512);
        eq("x-sup-g", "x^{g}", 0.3644);
        eq("x-prime", "x'", 0.2995);
        // Relations: thick glue both sides.
        eq("x-eq-x", "x=x", 0.8703);
        eq("x-leq-x", r"x\leq x", 0.8703);
        // Binaries: med glue both sides.
        eq("x-plus-x", "x+x", 0.8313);
        eq("x-otimes-y", r"x\otimes y", 0.8154);
        // Class glue in script styles: none.
        eq("script-eq", r"\scriptstyle x=x", 0.5345);
        eq("script-plus", r"\scriptstyle x+x", 0.5345);
        // Operator names: stacked limits never exceed the word here.
        eq("max-lim", r"\max_{x\in A}", 0.6541);
        eq("lim-lim", r"\lim_{x\in A}", 0.5601);
        eq("sum-lim", r"\sum_{k=0}^{\beta}", 0.5112);
        eq("int-lim", r"\int_{0}^{\zeta}", 0.5129);
        // Op -> Inner takes a thin space.
        eq("sum-frac", r"\sum\frac{a}{b}", 0.8364);
        // Ord -> Inner: none.
        eq("x-frac", r"x\frac{a}{b}", 0.4710);
        eq("frac-x", r"\frac{a}{b}x", 0.4710);
        eq("frac-frac", r"\frac{a}{b}\frac{c}{d}", 0.5374);
        // Ord/Inner -> Open: thin; Ord -> Close: none; Close -> Ord: thin.
        eq("x-lr", r"x\left(x\right)", 0.7337);
        eq("frac-lr", r"\frac{a}{b}\left(x\right)", 0.8029);
        eq("close-x", r"\left(x\right)x", 0.7337);
        // Nested fraction: num/den at text style.
        eq("frac-nest", r"\frac{\frac{s}{t}}{u}", 0.302);
        // Overset: max of the parts, no scriptspace.
        eq("overset-sim", r"\overset{\sim}{\vartheta}", 0.2197);
        // Punctuation: comma glyph; Punct -> Ord thin.
        eq("x-comma", "x,", 0.2985);
        eq("comma-x", ",x", 0.357);
        // Matrices: aligned columns + gap + bracket pair.
        eq("bmatrix", r"\begin{bmatrix} a & b \\ c & d \end{bmatrix}", 1.0906);
        eq("pmatrix", r"\begin{pmatrix} a & b \\ c & d \end{pmatrix}", 1.2372);
        eq("matrix", r"\begin{matrix} a & b \\ c & d \end{matrix}", 0.7198);
    }

    #[test]
    fn calibrated_composites() {
        // Whole-span truths from the probe (composite section).
        eq("vfrac", r"\frac{\vartheta(\zeta)}{\Gamma}", 0.7453);
        eq("vsumlim2", r"\sum_{k=0}^{\beta}\frac{\zeta}{k}", 0.8482);
        eq("vlimfrac", r"\lim_{n\to\infty}\frac{\sigma}{n}", 1.0905);
        eq("vmatmix", r"\begin{bmatrix} \vartheta & \zeta \\ \rho & \sigma \end{bmatrix}", 1.1438);
        eq("vlrainbow", r"\frac{\alpha}{\beta}+\sqrt{\gamma}\cdot\mathcal{S}\leq\Vert\varphi\Vert", 2.7774);
        eq("vunderset", r"\underset{\rho}{\text{max}}", 0.6541);
    }
}

